// Stand-in for Unity's `Resources.Load`: looks assets up by their path under `Assets/Resources`,
// which `src/lib/resources/` mirrors (partly generated by `scripts/convert-unity.ts`).
const modules = import.meta.glob<{ default: unknown }>("../../resources/**/*.ts", { eager: true })

const prefix = "../../resources/"

export const Resources = {
	/** Like `Resources.Load<T>(path)`: `path` has no extension; `null` if there is no such asset. */
	load<T>(path: string): T | null {
		const module = modules[`${prefix}${path}.ts`]
		return module ? (module.default as T) : null
	},

	/** Every asset path under `folder`, e.g. `paths("Levels")`. */
	paths(folder: string): string[] {
		const start = `${prefix}${folder}/`
		return Object.keys(modules)
			.filter((key) => key.startsWith(start))
			.map((key) => key.slice(prefix.length, -".ts".length))
			.sort()
	}
}
